from collections import Counter

def cumulative_value_counts(data, columns):
    values = sorted({v for row in data for v in row})
    result = {}
    for j, col in enumerate(columns):
        counts = Counter(row[j] for row in data)
        total = 0
        cdf = {}
        for v in values:
            total += counts[v]
            cdf[v] = total
        result[col] = cdf
    return result

