import pandas as pd

def cumulative_value_counts(data, columns):
    if not data:
        return {c: {} for c in columns}
    df = pd.DataFrame(data, columns=columns)
    table = pd.concat({c: df[c].value_counts() for c in columns}, axis=1)
    table = table.fillna(0).sort_index().cumsum()
    out = {}
    for c in columns:
        out[c] = {(k.item() if hasattr(k, 'item') else k): int(v) for k, v in table[c].items()}
    return out

