import statistics

def find_zscore_outliers(prices, z_threshold):
    if not prices:
        return []
    mu = statistics.fmean(prices)
    sigma = statistics.pstdev(prices)
    result = []
    for i, p in enumerate(prices):
        z = (p - mu) / sigma
        if abs(z) > z_threshold:
            result.append((i, p, z))
    return result

