import re
from collections import Counter


def bag_of_words_vector(text, sentences):
    def tokenize(s):
        return re.findall(r'\b\w\w+\b', s.lower())

    vocab = set(tokenize(text))
    for sentence in sentences:
        vocab.update(tokenize(sentence))
    counts = Counter(tokenize(text))
    return [counts[word] for word in sorted(vocab)]
